"""Report independent corrected-tracker validation with calibration limits."""
import time,math,json,re
import numpy as np
from run_mg172 import OUT,read,atomic_json

def report():
    start=time.perf_counter();s=read(OUT/'analysis.json');c=read(OUT/'separate_check.json');manifest=read(OUT/'local_raw_manifest.json');assert c['passed'];cal=c['calibration_diagnostics']
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    fig,axes=plt.subplots(1,2,figsize=(11,4.5),layout='constrained');conditions=[(.1,0.),(.1,.95),(1.,0.),(1.,.95)];x=np.arange(4)
    for name,color,offset in [('original','tab:orange',-.17),('corrected','tab:blue',.17)]:
        values=[sum(r[name]['successful_paths'] for r in s['rows'] if r['regime']==t and r['rho']==rho and r['case'] in('static','moving','deforming'))/12 for t,rho in conditions];axes[0].bar(x+offset,values,width=.34,color=color,label=name)
    axes[0].set_xticks(x,['Early iid','Early corr','Late iid','Late corr']);axes[0].set_ylim(0,1.05);axes[0].set_ylabel('Intact path success (pooled descriptive fraction)');axes[0].legend();axes[0].grid(axis='y',alpha=.2)
    for name,color,offset in [('original','tab:orange',-.17),('corrected','tab:blue',.17)]:
        values=[sum(r['high_weight_wrong_winner'] for r in cal if r['method']==name and r['regime']==t and r['rho']==rho) for t,rho in conditions];axes[1].bar(x+offset,values,width=.34,color=color,label=name)
    axes[1].set_xticks(x,['Early iid','Early corr','Late iid','Late corr']);axes[1].set_ylabel('High-weight wrong winners on in-model scenes');axes[1].legend();axes[1].grid(axis='y',alpha=.2);fig.savefig(OUT/'MG172_corrected_validation.png',dpi=160);plt.close(fig)
    positives=[r for r in s['rows'] if r['case'] in('static','moving','deforming')];new=sum(r['corrected']['successful_paths'] for r in positives);old=sum(r['original']['successful_paths'] for r in positives)
    lines=['# MG172 - corrected model-selection tracker validation','',
    f'The registered corrections remove the major spurious-multiple pathology on independent synthetic validation sequences and substantially improve tracking: the corrected version succeeds on {new}/48 intact paths versus {old}/48 for MG170. All late independent-noise intact paths pass, and no negative case has a false-single output at its predefined deadline. However, the full screen still fails: all four late, highly correlated static-core paths fail, accumulating73false-absent observations despite a core being present. This is meaningful progress on the audited inference error, not a qualified particle-persistence instrument. Model-relative weights can still be confidently wrong under the remaining assumptions; G stays unresolved and MG163 is unchanged.','',
    '![Corrected validation](MG172_corrected_validation.png)','',
    '## Corrections and remaining approximation','',
    'At each step the corrected version integrates the entire declared secondary-location/width prior, sums incoming history weights at equal endpoints, and calculates class weights before compressing geometry histories. The secondary grid contains13widths and435allowedpositions outside2R95for a designated primary. No observation-selected two-peak average or arbitrary fixed penalty is used. Stationary template cross-correlations accelerate the likelihood calculation; direct residual calculations check their equivalence.','',
    'For propagation it still retains only two geometry endpoints per nonabsent class and one absent anchor. It rescales the retained within-class weights to preserve the complete class mass. This preserves class totals, not the full geometry distribution, so it remains an approximate filter. The no-core hypothesis keeps an anchor for future primary motion; the secondary prior is globally redrawn each frame and does not track a separate secondary identity.','',
    'Same assumptions as MG170: known ordinary amplitude1, known conditional spectral covariance and temporal rho, five structural hypotheses, bounded primary motion/width increments, fixed class-transition priors, normalized-weight cutoff0.95and the conditional innovation fit guard. The fit guard uses the most-likely incoming history for the representative endpoint, not a mixture confidence interval. The comparison tests the three corrections together; it does not isolate their individual contributions. For a nonabsent prediction, geometry weight is spread uniformly over available neighboring states (normally 15, or 10 at a width boundary); remaining exactly still receives no special preference. Class-transition probability is 0.98 for staying in the same class and 0.005 for each other class. These are declared modeling choices, not measured Model G properties. Their role in the static correlated failure has not yet been isolated.','',
    '## Prospective independent test','',
    'Seed17200/source/input hashes were published at0f577e2and upload completion confirmed before draws. New synthetic sequences are independent realizations conditional on the same previously estimated regimes, not new Model G trajectories or independent real-vacuum validation. Each of160paths has24observations:fourreplicates for10cases inearly/late regimes withrho0/.95. Both trackers see identical fields and the same initial seed; no future truth is given. Motion, deformation, damage atframe10and the path/deadline criteria were frozen before outcomes.','',
    'Positive success requires>=22/24single labels and>=22/24estimates within2sites/.125width of truth. Four of four paths are needed to meet each raw90%screen. Negative success requires no single output at its fixed deadline:frame5for absent-from-start,frame15for other damage. Zero of four is the raw<=5%false-single screen, not certification of a population rate. No saved-MG163application was performed because the combined screen failed.','',
    '## Intact paths','',
    '| Regime | rho | Static corrected/original | Moving corrected/original | Deforming corrected/original |','|---|---:|---:|---:|---:|']
    for when,rho in conditions:
        cells=[]
        for case in('static','moving','deforming'):
            r=next(r for r in s['rows'] if r['regime']==when and r['rho']==rho and r['case']==case);cells.append(f"{r['corrected']['successful_paths']}/4 / {r['original']['successful_paths']}/4")
        lines.append(f'| {when:g} | {rho:g} | '+' | '.join(cells)+' |')
    lines+=['',
    'Under late independent noise, the original version labels277of288known intact observations multiple; the corrected version labels279single and9uncertain, with no false-multiple intact labels. That is a replication of the audited pathology on new fields and a substantial correction. The four late correlated static paths instead have only5,3,3,4single observations out of24and73absent labels between them. Their final model-relative absent weights are numerically indistinguishable from1at report precision. The corrected tracker still gives strong support to a known wrong explanation in this case.','',
    '## Damage/no-core deadlines','',
    '| Regime | rho | Absent | Vanish | X removed | Y removed | Y displaced | Split | Jump |','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
    for when,rho in conditions:
        cells=[next(r['corrected']['false_single_deadline'] for r in s['rows'] if r['regime']==when and r['rho']==rho and r['case']==case) for case in('absent','vanish','missingX','missingY','displacedY','split','jump')];lines.append(f'| {when:g} | {rho:g} | '+' | '.join(f'{v}/4' for v in cells)+' |')
    lines+=['',
    'All112negative-path deadlines avoid a single label. This does not mean immediate damage recognition or zero population false continuation: a deadline allows delay, intermediate labels can be wrong, and positive sensitivity is assessed separately. The new fields also produce four transient high-weight wrong class assignments in late independent-noise change cases before the deadline. All frame histories are retained.','',
    '## Weight calibration diagnostics','',
    '| Regime | rho | Corrected high-weight wrong winner / modeled frames | Original high-weight wrong winner / modeled frames |','|---|---:|---:|']
    for when,rho in conditions:
        cells=[]
        for name in('corrected','original'):
            rows=[r for r in cal if r['method']==name and r['regime']==when and r['rho']==rho];cells.append(f"{sum(r['high_weight_wrong_winner'] for r in rows)}/{sum(r['modeled_frames'] for r in rows)}")
        lines.append(f'| {when:g} | {rho:g} | '+' | '.join(cells)+' |')
    lines+=['',
    'These are diagnostic error counts on a deliberately balanced stress set, not a posterior-calibration guarantee for an assumed natural class distribution. The scenes used here have a known structural label among single/absent/X-only/Y-only/multiple; displaced-Y and post-jump model-violation frames are excluded from this particular table and reported in the endpoint tests. Frames within a path are correlated. In late correlated noise the remaining73wrong high-weight winners are all on the static intact cores. Thus preserving mass and integrating the prior fixes a major error without making0.95weights trustworthy confidence levels.','',
    '## Correctness checks, compute and retention','',
    f"No-draw deterministic fixtures preceded validation. Explicit endpoint history sums passed {s['explicit_endpoint_history_sum_checks']}checks during execution. A separate residual-FFT calculation, instead of the optimized cached cross-correlation formula, reproduced {c['explicit_secondary_grids_checked']}full secondary grids across24saved snapshots and {c['explicit_scalar_history_sums']}scalar endpoint history sums. Representative innovation quadratics matched in {c['representative_quadratics_checked']}snapshots. Independent replay verified {c['class_mass_preservation_checks']}class-mass checks, {c['frame_labels_checked']}frame labels and {c['path_outcomes_checked']}path outcomes. Shared covariance/templates and same-author work remain dependencies, not external replication.",'',
    f"Evaluation took {s['elapsed_seconds']:.6g}seconds on one worker/library-thread1, within600active seconds; separate checking took {c['elapsed_seconds']:.6g}seconds. Full independent synthetic fields and audit snapshots total {manifest['total_bytes']/1e6:.6g}MB locally in local_raw/MG172_corrected, below the100MBreserve. The SHA-256manifest verifies physical files. Public records are compact lossless gzip outputs, checks and source, not full fields; no immutable raw Git archive is claimed.",'',
    '## Frozen verdict and next step','',
    '**Overall independent conditional feasibility screen: FAILED.** The correction set has a clear verified benefit, but the static correlated case blocks qualification and any real-trajectory persistence application. No criteria were relaxed and no earlier result was rescored.','',
    'Next, audit the stationary-core motion prior and correlated-innovation history treatment against a small exact static-versus-absent reference calculation. Determine whether false absence comes from motion-prior mismatch, geometry compression or the available conditional evidence before changing priors or widening gaps. A known-static oracle is a diagnostic, not a replacement tracker; any new rule needs prospective independent validation. No new tracker revision or kinetic allocation is authorized by this report.','']
    text='\n'.join(lines)
    replacements={'accumulating73false-absent':'accumulating 73 false-absent','contains13widths and435allowedpositions outside2R95for':'contains 13 widths and 435 allowed positions outside 2R95 for','amplitude1':'amplitude 1','cutoff0.95and':'cutoff 0.95 and','Seed17200/source':'Seed 17200/source','at0f577e2and':'at 0f577e2 and','of160paths has24observations:fourreplicates for10cases inearly/late':'of 160 paths has 24 observations: four replicates for 10 cases in early/late','withrho0/.95':'with rho0/.95','atframe10and':'at frame 10 and','requires>=22/24single':'requires >=22/24 single','and>=22/24estimates within2sites/.125width':'and >=22/24 estimates within 2 sites/.125 width','raw90%screen':'raw 90% screen','deadline:frame5for':'deadline: frame 5 for','start,frame15for':'start, frame 15 for','raw<=5%false-single':'raw <=5% false-single','saved-MG163application':'saved-MG163 application','labels277of288known':'labels 277 of 288 known','labels279single and9uncertain':'labels 279 single and 9 uncertain','only5,3,3,4single':'only 5, 3, 3, 4 single','of24and73absent':'of 24 and 73 absent','from1at':'from 1 at','All112negative-path':'All 112 negative-path','remaining73wrong':'remaining 73 wrong','making0.95weights':'making 0.95 weights','}checks':'} checks','}full':'} full','across24saved':'across 24 saved','}scalar':'} scalar','}snapshots':'} snapshots','}class-mass':'} class-mass','}frame':'} frame','}path':'} path','}seconds':'} seconds','within600active':'within 600 active','}MB':'} MB','the100MBreserve':'the 100 MB reserve','SHA-256manifest':'SHA-256 manifest'}
    for old,new in replacements.items():text=text.replace(old,new)
    text=re.sub(r'(?<=\d)(checks|full|scalar|snapshots|class-mass|frame|path|seconds|MB)',r' \1',text)
    (OUT/'MG172_corrected_model_selection_results.md').write_text(text,encoding='utf-8');atomic_json(OUT/'report_attempt_v3.json',dict(status='COMPLETE',elapsed_seconds=time.perf_counter()-start))
if __name__=='__main__':report()
